import{_ as i,a0 as d,w as n,s,ao as p,I as l,x as o,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"Fedora 上的桌面環境內存佔用測試 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 上的桌面環境內存佔用測試 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 上的桌面環境內存佔用測試 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 上的桌面環境內存佔用測試 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191204 Fedora Desktops - Memory Footprints","title":"Fedora 上的桌面環境內存佔用測試","tag":"201912","desc":""},"relativePath":"201912/20191204 Fedora Desktops - Memory Footprints.md","filePath":"[post].md"}'),m={name:"201912/20191204 Fedora Desktops - Memory Footprints.md"};function u(f,e,g,h,x,T){const t=d("Link");return n(),s("div",null,[e[15]||(e[15]=p('<h1 id="fedora-上的桌面環境內存佔用測試" tabindex="-1">Fedora 上的桌面環境內存佔用測試 <a class="header-anchor" href="#fedora-上的桌面環境內存佔用測試" aria-label="Permalink to “Fedora 上的桌面環境內存佔用測試”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/11/desktop-memory-footprint-816x346.jpg" alt=""></p><p>Fedora 中有 40 多種桌面環境（DE）。每種桌面環境都有自己的優點和缺點。通常，根據功能、外觀和其它品質，選擇桌面是一件非常個人的偏好。但有時，你選擇的桌面環境還會受到硬件限制。</p><p>本文旨在幫助人們根據桌面環境佔用的基準內存來比較 Fedora 桌面環境。為了縮小範圍，我們僅查看具有正式 Fedora Live 鏡像的桌面環境。</p><h3 id="安裝與系統配置" tabindex="-1">安裝與系統配置 <a class="header-anchor" href="#安裝與系統配置" aria-label="Permalink to “安裝與系統配置”">​</a></h3><p>每個桌面環境都安裝在自己的 KVM 虛擬機上。每個虛擬機都有 1 個 CPU、4GB 內存、15GB virtio 固態磁盤，以及 RHEL 8.0 kvm 上所有其他標準配置。</p><p>用於安裝的鏡像是標準的 Fedora 31 Live 鏡像。對於 GNOME，該鏡像是 “Fedora 工作站”。對於其它桌面，使用了相應的 Spin 版本。未對“<ruby>糖葫蘆<rt>Sugar On A Stick</rt></ruby>”（SOAS）進行測試，因為它不容易安裝到本地驅動器上。</p><p>用 Live CD 啓動虛擬機，然後選擇“安裝到硬盤”。在安裝過程中，僅使用默認值。創建了一個 root 用户和一個普通用户。安裝並重新啓動後，live 鏡像已確認不在虛擬 CDROM 中。</p><p>每個桌面環境的設置都沒有改動。它們每個都以 Live CD 環境中默認的設置運行。每個桌面環境都是通過普通用户登錄的。打開了一個終端，在每台虛擬機中都使用 <code>sudo</code> 運行了 <code>dnf -y update</code>。在更新後，在該 sudo 終端中，每台虛擬機都運行 <code>/sbin/shutdown -h now</code> 以關閉。</p><h3 id="測試方式" tabindex="-1">測試方式 <a class="header-anchor" href="#測試方式" aria-label="Permalink to “測試方式”">​</a></h3><p>每台機器都已啓動。桌面環境已通過普通用户登錄。打開了三個桌面終端。xterm 從未使用過，始終用的是該桌面環境的終端，例如 konsole。</p><p>在一個終端中，啓動 <code>top</code> 並按下 <code>M</code>，以顯示按內存排序的進程。在另一個終端中，一個簡單的 <code>while</code> 循環每 30 秒顯示一次 <code>free -m</code>。第三個終端閒置。</p><p>然後，我等待了 5 分鐘。這樣就可以讓所有啓動的服務都啓動完成。我記錄了最終的 <code>free</code> 結果，以及 <code>top</code> 中最終的前三名內存使用者。</p><h3 id="結果" tabindex="-1">結果 <a class="header-anchor" href="#結果" aria-label="Permalink to “結果”">​</a></h3><ul><li>Cinnamon <ul><li>使用了624 MB</li><li>cinnamon 4.8% / Xorg 2.2% / dnfdragora 1.8%</li></ul></li><li>GNOME <ul><li>使用了 612 MB</li><li>gnome-shell 6.9% / gnome-software 1.8% / ibus-x11 1.5%</li></ul></li><li>KDE <ul><li>使用了 733 MB</li><li>plasmashell 6.2% / kwin_x11 3.6% / akonadi_mailfil 2.9%</li></ul></li><li>LXDE <ul><li>使用了 318 MB</li><li>Xorg 1.9% / nm-applet 1.8% / dnfdragora 1.8%</li></ul></li><li>LXQt <ul><li>使用了 391 MB</li><li>lxqt-panel 2.2% / pcmanfm-qt 2.1% / Xorg 2.1%</li></ul></li><li>MATE <ul><li>使用了 465 MB</li><li>Xorg 2.5% / dnfdragora 1.8% / caja 1.5%</li></ul></li><li>XFCE <ul><li>使用了 448 MB</li><li>Xorg 2.3% / xfwm4 2.0% / dnfdragora 1.8%</li></ul></li></ul><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我會讓數字説明一切。</p><p>請記住，這些數字來自默認的 Live 安裝環境。如果刪除或添加服務和功能，則內存使用量將發生變化。但是，如果要根據內存消耗確定桌面環境，這是一個很好的基準。</p><hr>',19)),l("p",null,[e[1]||(e[1]=o("via: ",-1)),a(t,{href:"https://fedoramagazine.org/fedora-desktops-memory-footprints/"},{default:r(()=>[...e[0]||(e[0]=[o("https://fedoramagazine.org/fedora-desktops-memory-footprints/",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=o("作者：",-1)),a(t,{href:"https://fedoramagazine.org/author/tdawson/"},{default:r(()=>[...e[2]||(e[2]=[o("Troy Dawson",-1)])]),_:1}),e[7]||(e[7]=o(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[3]||(e[3]=[o("lujun9972",-1)])]),_:1}),e[8]||(e[8]=o(" 譯者：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1}),e[9]||(e[9]=o(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[o("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=o("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[o("Linux中國",-1)])]),_:1}),e[14]||(e[14]=o(" 榮譽推出",-1))])])}const M=i(m,[["render",u]]);export{F as __pageData,M as default};
